module.exports = function(RED) {
    const sessionManager = require("../../runtime/session-manager").getInstance(RED);

    function AskQuestionNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', async function(msg) {
            const sessionId = msg.sessionId;
            if (!sessionId) return node.error("No sessionId");

            // In real implementation you would trigger voice prompt via Africa's Talking action
            // For now we just wait
            msg._questionText = config.ttsText;
            node.send(msg); // Pass through to next (Wait node in full flow)
        });
    }
    RED.nodes.registerType("ask-question", AskQuestionNode);
};